@@ -1,4 +1,8 @@
 import Database from "better-sqlite3";
+import fs from "fs";
+import path from "path";
+import os from "os";
+import { execSync } from "child_process";

 export interface RecordRow {
   recordId: string;
@@ -7,8 +11,108 @@ export interface RecordRow {
   trailer: string;
 }

-export const openIndex = (gitDir: string): Database.Database =>
-  new Database(`${gitDir}/commitlore/index.db`);
+interface CacheMetadata {
+  version: number;
+  gitStateHash: string;
+  timestamp: number;
+}
+
+const getCacheDir = (): string => {
+  const cacheDir =
+    process.env.XDG_CACHE_HOME || path.join(os.homedir(), ".cache");
+  return path.join(cacheDir, "commitlore");
+};
+
+const getCacheMetadataPath = (repoRoot: string): string => {
+  const cacheDir = getCacheDir();
+  const repoHash = hashPath(repoRoot);
+  return path.join(cacheDir, `metadata-${repoHash}.json`);
+};
+
+const getSharedIndexPath = (repoRoot: string): string => {
+  const cacheDir = getCacheDir();
+  const repoHash = hashPath(repoRoot);
+  return path.join(cacheDir, `index-${repoHash}.db`);
+};
+
+const hashPath = (str: string): string => {
+  let hash = 0;
+  for (let i = 0; i < str.length; i++) {
+    const char = str.charCodeAt(i);
+    hash = (hash << 5) - hash + char;
+    hash = hash & hash;
+  }
+  return Math.abs(hash).toString(36);
+};
+
+const getGitStateHash = (gitDir: string): string => {
+  try {
+    // Use the HEAD ref and all ref heads to create a state hash
+    const headSha = execSync(`git rev-parse HEAD`, {
+      cwd: gitDir,
+      encoding: "utf-8",
+    }).trim();
+    const refsSha = execSync(`git show-ref --head`, {
+      cwd: gitDir,
+      encoding: "utf-8",
+    }).trim();
+    return hashPath(`${headSha}:${refsSha}`);
+  } catch {
+    return "unknown";
+  }
+};
+
+const isCacheValid = (gitDir: string): boolean => {
+  const repoRoot = path.dirname(gitDir);
+  const metadataPath = getCacheMetadataPath(repoRoot);
+  const indexPath = getSharedIndexPath(repoRoot);
+
+  if (!fs.existsSync(metadataPath) || !fs.existsSync(indexPath)) {
+    return false;
+  }
+
+  try {
+    const metadata: CacheMetadata = JSON.parse(
+      fs.readFileSync(metadataPath, "utf-8")
+    );
+    const currentStateHash = getGitStateHash(gitDir);
+
+    return (
+      metadata.version === 1 && metadata.gitStateHash === currentStateHash
+    );
+  } catch {
+    return false;
+  }
+};
+
+const saveCacheMetadata = (gitDir: string): void => {
+  const repoRoot = path.dirname(gitDir);
+  const cacheDir = getCacheDir();
+  const metadataPath = getCacheMetadataPath(repoRoot);
+
+  fs.mkdirSync(cacheDir, { recursive: true });
+
+  const metadata: CacheMetadata = {
+    version: 1,
+    gitStateHash: getGitStateHash(gitDir),
+    timestamp: Date.now(),
+  };
+
+  fs.writeFileSync(metadataPath, JSON.stringify(metadata, null, 2));
+};
+
+export const openIndex = (gitDir: string): Database.Database => {
+  const repoRoot = path.dirname(gitDir);
+
+  // Try to use shared cache if valid
+  if (isCacheValid(gitDir)) {
+    const sharedIndexPath = getSharedIndexPath(repoRoot);
+    return new Database(sharedIndexPath);
+  }
+
+  // Fall back to local index for backward compatibility and rebuilds
+  return new Database(`${gitDir}/commitlore/index.db`);
+};

 export const rebuild = (db: Database.Database, rows: readonly RecordRow[]): void => {
   db.exec("DROP TABLE IF EXISTS records");
@@ -16,3 +120,31 @@ export const rebuild = (db: Database.Database, rows: readonly RecordRow[]): void
   const insert = db.prepare("INSERT INTO records VALUES (?, ?, ?, ?)");
   for (const row of rows) insert.run(row.recordId, row.sha, row.path, row.trailer);
 };
+
+export const cacheRebuild = (
+  gitDir: string,
+  db: Database.Database,
+  rows: readonly RecordRow[]
+): void => {
+  // Perform the rebuild
+  rebuild(db, rows);
+
+  // Save to shared cache if this is a local index
+  if (db.name.includes(`${gitDir}/commitlore`)) {
+    const repoRoot = path.dirname(gitDir);
+    const cacheDir = getCacheDir();
+    const sharedIndexPath = getSharedIndexPath(repoRoot);
+
+    try {
+      fs.mkdirSync(cacheDir, { recursive: true });
+      // Copy the rebuilt local index to shared cache
+      fs.copyFileSync(db.name, sharedIndexPath);
+      saveCacheMetadata(gitDir);
+    } catch (err) {
+      console.warn(
+        `Failed to cache index: ${err instanceof Error ? err.message : err}`
+      );
+      // Non-fatal: rebuild succeeded locally, cache save is optional
+    }
+  }
+};
